const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sakha = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Sakha'));

  const summer2021 = ['2021-06-01', '2021-08-31'];

  // 2. Data Acquisition - MODIS Burned Area
  const burnedCol = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterBounds(sakha)
    .filterDate(summer2021[0], summer2021[1]);

  // Check collection size
  const colSize = burnedCol.size().getInfo();
  console.log(`Summer 2021 burned area images: ${colSize}`);

  if (colSize === 0) {
    console.log("No burned area data found for summer 2021.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create burned area mask and calculate area
  const burnedArea = burnedCol.select('BurnDate').max();

  // Create binary burned mask (BurnDate > 0 indicates burned)
  const burnedMask = burnedArea.gt(0);

  // Calculate pixel count and area
  const pixelStats = burnedMask.reduceRegion({
    reducer: ee.Reducer.sum().unweighted(),
    geometry: sakha,
    scale: 500,  // MODIS resolution
    maxPixels: 1e10
  });

  const burnedPixels = pixelStats.get('BurnDate').getInfo();
  console.log(`Burned pixels: ${burnedPixels}`);

  if (burnedPixels === 0 || burnedPixels === null) {
    console.log("No burned pixels detected.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Convert to hectares (500m resolution = 25 hectares per pixel)
  const hectaresPerPixel = 0.25; // 500m × 500m = 0.25 hectares
  const totalBurnedHectares = burnedPixels * hectaresPerPixel;

  console.log(`Total burned area: ${totalBurnedHectares.toLocaleString()} hectares`);

  // 5. Validation & Final Answer
  if (totalBurnedHectares === null || totalBurnedHectares === undefined || 
      !isFinite(totalBurnedHectares) || totalBurnedHectares < 0) {
    console.log("Invalid calculation result.");
    console.log("<answer>C3</answer>");
  } else if (totalBurnedHectares >= 6000000) {
    console.log("Burned area meets/exceeds 6 million hectares.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Burned area less than 6 million hectares.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
